import Image from "next/image";

// A rendered first page of a template (generated by `pnpm thumbnails`).
export function TemplateThumb({ id, name, priority = false, sizes = "(min-width: 1024px) 260px, 45vw" }: { id: string; name: string; priority?: boolean; sizes?: string }) {
  return (
    <div className="relative aspect-[8.5/11] overflow-hidden rounded-md bg-white ring-1 ring-line">
      <Image src={`/templates/${id}.png`} alt={`${name} template`} fill sizes={sizes} priority={priority} className="object-cover object-top" />
    </div>
  );
}
